args.oldStr:
.about__inner {
  display: flex;
  align-items: center;
  gap: var(--space-lg);
  max-width: 900px;
  margin: 0 auto;
}

.about__img {
  width: 280px;
  height: 280px;
  object-fit: cover;
  clip-path: polygon(0 0, 90% 0, 100% 10%, 100% 100%, 10% 100%, 0 90%);
  flex-shrink: 0;
}

args.newStr:
.about__inner {
  display: flex;
  align-items: center;
  flex-wrap: wrap;         /* graceful wrap on intermediate widths */
  gap: var(--space-lg);
  max-width: 900px;
  margin: 0 auto;
}

/* Avatar wrapper — zero out figure default margin */
.about__avatar {
  flex-shrink: 0;
  position: relative;
  line-height: 0; /* collapse whitespace below inline img */
}

/* Offset geometric accent — P5 frame treatment */
.about__avatar::after {
  content: '';
  position: absolute;
  inset: 10px -10px -10px 10px; /* offset down-right */
  border: 2px solid var(--color-red);
  clip-path: polygon(0 0, 90% 0, 100% 10%, 100% 100%, 10% 100%, 0 90%);
  pointer-events: none;
}

.about__img {
  /* Relative sizing: fluid up to 280px on wide viewports */
  width: clamp(180px, 28vw, 280px);
  height: clamp(180px, 28vw, 280px);
  object-fit: cover;
  clip-path: polygon(0 0, 90% 0, 100% 10%, 100% 100%, 10% 100%, 0 90%);
  display: block;
}

args.oldStr:
/* About: stack portrait above text */
.about__inner {
