}

.about__img {
  width: 200px;
  height: 200px;
}

args.newStr:
/* About: stack portrait above text */
.about__inner {
  flex-direction: column;
  text-align: center;
}

/* Avatar accent shifts for centered layout */
.about__avatar::after {
  inset: 8px -8px -8px 8px;
}

/* clamp() already scales the image — override only to centre it */
.about__img {
  margin: 0 auto;
}
